import { chainClient } from './client.js';
import { cachedEvents } from './event-store.js';

// The NFT emits Transfer for minting and lender seizures. One cached event
// stream supplies the complete catalog, instead of re-reading 32 owners on
// every poll. The shared cache verifies hashes and reads only new blocks.
export async function readDeityCatalog({ client = chainClient(), signal } = {}) {
  const snapshot = await client.snapshot({ signal });
  const transfers = await cachedEvents(snapshot, 'DEITY_PASS', 'Transfer', {}, { signal });
  const ownersBySymbol = new Map();
  for (const { args } of transfers) {
    const symbol = Number(args.tokenId);
    if (!Number.isInteger(symbol) || symbol < 0 || symbol >= 32) throw new Error('Invalid deity symbol.');
    const owner = args.to.toLowerCase();
    if (/^0x0{40}$/.test(owner)) ownersBySymbol.delete(symbol);
    else ownersBySymbol.set(symbol, owner);
  }
  await snapshot.verify(signal);
  return { issuedCount: ownersBySymbol.size, takenSymbols: new Set(ownersBySymbol.keys()), ownersBySymbol };
}
